    var chain = chainNameOf(source.chain)
      || (typeof source.chain === 'string' && source.chain.trim() ? source.chain.trim().slice(0, 64) : null);
    // The reaction may REPLACE a line that is currently up — that is the difference between being asked and
    // interrupting — but not faster than the gap allows.
    var t = this.now();
    var gap = PRESS_LIMITS.reactGapSeconds * 1000;
