      var resumed = snap.running === true
        && isFiniteNumber(Number(snap.runningSince))
        && Number(snap.runningSince) > this.pendingNotice.endedAt
        && (!pendingSession || !snap.currentSessionId || pendingSession === snap.currentSessionId);
