    var freshNotice = acknowledged ? undefined : notice;

    /**
     * The pending LATCH.
     *
     * 等待确认 is not an ordinary precedence branch: the operator's rule is "等待确认状态必须完成确认项目后才
     * 可以跳转出来" — the pet may not leave that state until the thing it is waiting for has actually been
     * answered. Re-deriving the state from the session every frame normally does that on its own, but not
     * when something else outranks 等待确认 in this cascade: a turn that ends in failure while a question is
     * still on screen would flip the pet to 出错 and hide the very prompt the user has to answer, and a
     * turn that completes would show 任务达成 over an unanswered approval.
     *
     * So while the session reports a pending interaction, EVERY other branch is skipped except the two the
     * user owns by hand (a drag, and a click they just made). When the interaction is answered the session
     * stops reporting it, this latch releases, and the same frame's cascade decides where the pet goes.
     */
    var pending = snap.pending === true;
    if (pending) this.pendingKind = typeof snap.pendingKind === 'string' && snap.pendingKind ? snap.pendingKind : 'question';
    else if (this.state !== 'waiting') this.pendingKind = null;

    // DSH's unread-completion count, straight through: the prompt draws its green dot from this and nothing else.
    this.unreadCount = isFiniteNumber(Number(snap.unreadCount)) && Number(snap.unreadCount) > 0
      ? Math.floor(Number(snap.unreadCount))
      : 0;

