      sleeping: { breath: 2.2, sway: 0.25 },
      error: { breath: 0.9, sway: 0.3 },
      greeting: { breath: 1.3, sway: 1.5 },
      offline: { breath: 0.5, sway: 0.15 },
      held: { breath: 0.7, sway: 1.6 },
      falling: { breath: 0.6, sway: 2.2 },
