    // limb happens to be exactly perpendicular to its target. Returning it raw is
    // not a small thing: the caller builds a quaternion from this axis, and a
    // quaternion made from a non-unit axis is itself non-unit — three.js's
    // `setFromAxisAngle` does not normalise. That is what made the arms' stance
    // 0.999599 long (measured on SampleModel.vrm, 2026-10-12), which nothing
    // downstream noticed except a test that compared two of those quaternions with
    // `Quaternion.angleTo`: it read the length difference as a 4.59 deg pose
    // residual and failed two rest-pose checks on every clip that drives an arm.
    // `normalize3` was already being called here — its result was just discarded.
    var unitCross = normalize3(cross);
    // Parallel or antiparallel: any perpendicular axis is as good as another, and
    // acos already took care of the angle, so pick a stable one rather than NaN.
    if (!unitCross) unitCross = perpendicular3(axis);

